{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C20"],
      "claim": "Antipyrine, a structurally related N-phenyl carbonyl heterocycle, was used as a high-permeability reference in the rat in situ brain perfusion model, demonstrating rapid brain uptake for this compound class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Antipyrine showed good unbound brain penetration in rat microdialysis and was classified as not subject to efflux, supporting meaningful CNS access for similar neutral, moderately lipophilic heterocycles.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "4-Aminoantipyrine, another N-phenyl pyrazolone analogue, reached a CSF/plasma ratio of 0.62 in humans, providing direct evidence that this chemotype crosses the blood-CSF barrier.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Metamizol-derived N-phenyl heterocyclic species reached 15 µg/g in rat brain after oral administration, confirming CNS access for this structural family.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is ebselen, a low-molecular-weight, neutral, lipophilic benzisoselenazolone with favorable passive BBB properties. Direct evidence from closely related N-phenyl carbonyl heterocycles, especially antipyrine and dipyrone metabolites, shows high BBB/CSF penetration and no efflux liability. Poorly penetrating comparators such as quinazoline-2,4-dione and kynurenic acid are much more polar or ionized and do not transfer to this scaffold. Therefore, meaningful CNS access is predicted.",
  "evidence_gaps": [
    "No direct brain or CSF measurement for ebselen itself was provided.",
    "Morgan similarities to the supporting evidence are modest (<0.3), so transfer relies on shared N-phenyl carbonyl heterocycle features rather than exact scaffold identity.",
    "Selenium-specific CNS pharmacokinetic behavior is not directly covered by the evidence set."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

